"""Output escaping helpers for MiniJinja CLI rendering."""
import html
import json
import os


def mode_for_template(mode="auto", filename=None):
    """Resolve the auto mode from a template path's extension."""
    if mode != "auto":
        return mode
    ext = os.path.splitext(filename)[1].lower() if filename else ""
    if ext in (".html", ".htm", ".xml", ".xhtml"):
        return "html"
    if ext == ".json":
        return "json"
    return "none"


def escape_output(value, mode="none", filename=None, safe=False):
    """Render one interpolated value, honoring html/json autoescape modes."""
    mode = mode_for_template(mode, filename)
    if safe:
        return stringify(value)
    if mode == "json":
        # JSON autoescape is serialization of the interpolation, not HTML escaping.
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    if mode == "html":
        return html.escape(stringify(value), quote=True)
    return stringify(value)


def stringify(value):
    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, (list, tuple)):
        return "[" + ", ".join(stringify(v) for v in value) + "]"
    if isinstance(value, dict):
        return "{" + ", ".join(stringify(k) + ": " + stringify(v) for k, v in value.items()) + "}"
    return str(value)

