"""A small stdlib-only minijinja-cli compatible command line renderer."""
import argparse
import configparser
import json
import os
import sys
import urllib.parse

import advanced
import autoescape
import templating


def parse_define(text):
    if ':=' in text:
        k, v = text.split(':=', 1)
        try: value = json.loads(v)
        except Exception: value = v
    elif '=' in text:
        k, value = text.split('=', 1)
    else:
        k, value = text, True
    return k, value


def load_data(path, fmt):
    raw = sys.stdin.read() if path == '-' else open(path, encoding='utf-8').read()
    f = fmt
    if f == 'auto':
        ext = os.path.splitext(path)[1]
        f = {'.json':'json','.json5':'json','.toml':'toml','.ini':'ini','.conf':'ini','.config':'ini','.properties':'ini','.qs':'querystring','.yaml':'yaml','.yml':'yaml'}.get(ext)
        if f is None: raise ValueError('cannot detect format for ' + path)
    if f in ('json','json5'): return json.loads(raw)
    if f == 'toml':
        import tomllib
        return tomllib.loads(raw)
    if f == 'querystring':
        parsed = urllib.parse.parse_qs(raw, keep_blank_values=True)
        return {k: v[-1] if len(v)==1 else v for k,v in parsed.items()}
    if f == 'ini':
        p = configparser.ConfigParser()
        p.read_string(raw)
        out = {'default': dict(p.defaults())}
        for sec in p.sections(): out[sec] = dict(p.items(sec))
        return out
    if f == 'yaml':
        # Support JSON-compatible YAML and simple key/value mappings without dependencies.
        try: return json.loads(raw)
        except Exception: pass
        result = {}
        for line in raw.splitlines():
            line = line.split('#',1)[0].strip()
            if not line or ':' not in line: continue
            k,v=line.split(':',1); v=v.strip()
            if v.lower() in ('true','false'): val=v.lower()=='true'
            elif v.lower() in ('null','none','~'): val=None
            else:
                try: val=json.loads(v)
                except Exception: val=v.strip('"\'')
            result[k.strip()] = val
        return result
    raise ValueError('unsupported data format: '+f)


def select_data(ctx, selector):
    for part in selector.split('.'):
        if isinstance(ctx, dict): ctx = ctx.get(part)
        elif isinstance(ctx, list): ctx = ctx[int(part)]
        else: return None
    return ctx


def main(argv=None):
    p = argparse.ArgumentParser(prog='minijinja-cli', description='Render or evaluate jinja2 templates.')
    p.add_argument('template_file', nargs='?', default='-')
    p.add_argument('data_files', nargs='*')
    p.add_argument('-f','--format',default=os.environ.get('MINIJINJA_FORMAT','auto'),choices=['auto','cbor','ini','json','querystring','toml','yaml'])
    p.add_argument('-D','--define',action='append',default=[])
    p.add_argument('-t','--template')
