"""Filesystem policy helpers for MiniJinja-style include and extends loading."""
from pathlib import Path


class IncludeError(Exception):
    pass


def resolve_template(name, current_template="-", safe_paths=(), includes=True):
    """Resolve a referenced template and return (canonical path, source text).

    Relative names are looked up beside the current template. A name that does
    not exist returns None so callers can implement include-choice/ignore-missing.
    """
    if not includes:
        return None
    raw = Path(name)
    base = Path(current_template).resolve().parent if current_template not in (None, "", "-") else Path.cwd()
    target = raw if raw.is_absolute() else base / raw
    try:
        # Canonicalize existing symlink components while retaining a normalized
        # path for missing candidates: security checks happen before existence.
        target = target.resolve(strict=False)
    except (OSError, RuntimeError):
        return None
    if safe_paths:
        roots = []
        for root in safe_paths:
            try:
                roots.append(Path(root).resolve(strict=True))
            except (OSError, RuntimeError):
                continue
        trusted = any(target == root or root in target.parents for root in roots)
        if not trusted:
            raise IncludeError("Cannot include template from non-trusted path")
    if not target.is_file():
        return None
    try:
        return str(target), target.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return None


def resolve_template_choice(names, current_template="-", safe_paths=(), includes=True):
    """Resolve the first existing name in an include/extends candidate list."""
    if isinstance(names, (str, bytes)):
        names = [names]
    for name in names:
        found = resolve_template(str(name), current_template, safe_paths, includes)
        if found is not None:
            return found
    return None

